"""General usage descriptions for demo equipment; no unverified model specifications."""

DEMO_PLACEHOLDER='ข้อมูลตัวอย่างสำหรับทดลองระบบภายในโรงเรียน'
DESCRIPTIONS={
    'camera':'กล้องสำหรับถ่ายภาพและวิดีโอในงานเรียน กิจกรรมโรงเรียน และงานประชาสัมพันธ์\nก่อนรับ: ตรวจตัวกล้อง เลนส์ แบตเตอรี่ และอุปกรณ์ที่เจ้าหน้าที่ส่งมอบ\nการดูแล: ใช้สายคล้อง หลีกเลี่ยงน้ำและแรงกระแทก ปิดเครื่องและเก็บอุปกรณ์ให้เรียบร้อยก่อนคืน',
    'projector':'โปรเจกเตอร์สำหรับฉายสไลด์และสื่อประกอบการเรียนหรือกิจกรรม\nก่อนรับ: ตรวจพอร์ตและสายเชื่อมต่อที่ต้องใช้กับคอมพิวเตอร์ร่วมกับเจ้าหน้าที่\nการดูแล: วางบนพื้นมั่นคง ไม่ปิดช่องระบายอากาศ และปิดเครื่องตามขั้นตอนก่อนเคลื่อนย้าย',
    'microphone':'ไมโครโฟนสำหรับพูดนำเสนอ พิธีกร และกิจกรรมที่ต้องใช้เสียง\nก่อนรับ: ตรวจตัวไมโครโฟนและอุปกรณ์ที่ต้องใช้ร่วมกันกับเจ้าหน้าที่\nการดูแล: จับบริเวณด้าม หลีกเลี่ยงการตกกระแทกและน้ำ ปิดหรือถอดการเชื่อมต่อเมื่อใช้เสร็จ',
    'speaker':'ลำโพงสำหรับขยายเสียงในการนำเสนอและกิจกรรมโรงเรียน\nก่อนรับ: ตรวจช่องเชื่อมต่อ สายสัญญาณ และแหล่งจ่ายไฟกับเจ้าหน้าที่\nการดูแล: วางให้มั่นคง หลีกเลี่ยงน้ำ และลดระดับเสียงก่อนเปิดหรือปิดชุดเสียง',
    'notebook':'คอมพิวเตอร์โน้ตบุ๊กสำหรับทำงานเอกสาร นำเสนอ และใช้สื่อการเรียน\nก่อนรับ: ตรวจหน้าจอ แป้นพิมพ์ แบตเตอรี่ และอะแดปเตอร์ที่ส่งมอบ\nการดูแล: หลีกเลี่ยงอาหารและเครื่องดื่ม สำรองงานส่วนตัวและออกจากบัญชีที่ใช้งานก่อนคืน',
    'tripod':'ขาตั้งกล้องสำหรับช่วยให้ภาพนิ่งขณะถ่ายภาพหรือวิดีโอ\nก่อนรับ: ตรวจหัวจับ ตัวล็อกขา และความเข้ากันได้กับกล้องร่วมกับเจ้าหน้าที่\nการดูแล: ตั้งบนพื้นเรียบ ล็อกขาให้แน่นก่อนใช้งาน ถอดกล้องและพับขาให้เรียบร้อยก่อนคืน',
}


def demo_description(kind,name=''):
    if str(name).strip().casefold()=='tripod':kind='tripod'
    return DESCRIPTIONS.get(kind,DEMO_PLACEHOLDER)
